from pathlib import Path
import json,csv,hashlib,shutil
P=Path(__file__).resolve().parent;A=P.parent/'t1b_inputs/Leviathan/Repro/E15_T1_A'
rows=list(csv.DictReader((A/'state_results.csv').open()));base=min([float(r['nominal_radius']) for r in rows]+[float(r['r_conj']) for r in rows if r['r_conj']]);fractions=[.25,.5,.75,.9]
protocol={'version':'T1-B-1','status':'FROZEN_BEFORE_NEW_RESULTS','scope':'80 original states, descriptive only; original C1 and T1A unchanged','radius_rule':'base=min(all 80 archived nominal radii, both detected first conjugate estimates); fixed fractions [0.25,0.5,0.75,0.90]; uses prior geometric bounds only, never correlation optimization','radius_base':base,'radius_fractions':fractions,'radii':[base*x for x in fractions],'primary_radius_index':2,'primary_radius':base*.75,'domain_limit':'all common radii below nominal and first detected folding; numerical validity tested, not global certificate','geometry':'identical saved M/f and geometry.py; checkpoints checked SHA; no retraining','rho':1e-4,'center':[0,0],'DOP853':{'rtol':2e-10,'atol':2e-12},'angular_resolutions':[256,512],'phases_cells':[0,.5],'primary_summary':'max over angles of intrinsic max(1,abs(j/r))/min(1,abs(j/r)) at endpoint ri, pooled two phases of 512','secondary_summary':'max over sampled prefix 0<t<=ri using 512 common radial intervals and same angular grid','nominal_comparators':['original T1A disk maximum, common Jacobi512 both phases','nominal endpoint maximum from final row of the same stored arrays'],'nominal_CA':'retain C1 admissible CA only; no CA for two invalid domains; no artificial zeros','numerical_gates':{'SPD':True,'positive_signed_determinant_on_sampled_prefix':True,'simple_common_boundary':True,'condition_resolution_agreement_abs_plus_relative':'1e-6 + .005*abs(kappa512-1)','determinant_resolution_agreement_abs_plus_relative':'1e-6 + .005*abs(det512)','failure_policy':'document state/radius INCONCLUSIVE, no replacement or radius reduction; no further adaptive tuning'},'auxiliary_angular_observables':['endpoint K signed mean,RMS,maxabs,absolute CV,std/RMS,peak/RMS,top10% of K^2 by launch angle','theta of largest kappa','fraction det<0.5; det quantiles; angular kappa quantiles'],'correlations':{'regimes_separate':True,'methods':['Spearman','paired differences versus both nominal comparators'],'bootstrap':'5000 cluster resamples of8 splits, retaining all eligible states in sampled block; percentile2.5/97.5; descriptive sensitivity intervals only due overlapping splits','bootstrap_seed':151510,'leave_one_state_out':'all available states, not selected after results','leave_one_split_out':'all8; also within split correlations with n>=3','no_p_values':True},'positive_cases':{'include_all_common_radii':True,'ranks':'against all40 true, descending kappa; also full80 as supplementary','tail_rule':'top4 of40 true (top10%), descriptive predeclared; no predictive/confirmation claim'},'residual_model':{'family':'monotone increasing isotonic regression','x':'log10(C_A)','y':'log10(max(kappa_endpoint-1,1e-12))','crossfit':'leave-one-split-out; prediction clipped to training x range and extrapolation flagged','residual':'observed log-deformation minus crossfit prediction','large_rule':'abs(residual)>log10(2), i.e. factor2 deformation error; also robust z using 1.4826*MAD reported without retuning','primary_radius_index':2,'no_residual_for_missing_CA':True},'residual_features':['Lambda1%','Lambda0.1%','R_eff','f50','f90','nominal_radius','angular_K_abs_cv','angular_K_peak_to_rms','angular_K_top10_energy','r_conj/r_inj/A_embed where available; censoring retained'],'fixed_area_analysis':{'always_run':True,'large_rho_drop_descriptive_threshold':.10,'radius_rank_associations':True,'partial_rank_correlation_control_Rnom':'descriptive only; not mediation identification','dimensionless_candidates':['C_A*0.02/(4*pi), rank-equivalent to CA','C_A*Rnom^2','C_A*ri^2 at common radius, rank-equivalent to CA'],'candidate_prediction':'same leave-one-split-out isotonic log-deformation; MAE descriptive only'},'evidence_levels':['EXPECTED_GEOMETRIC_CONTROL','EXPLORATORY_STRUCTURE','NEW_HYPOTHESIS'],'confirmation':'new states only; no T2 execution here; write exact future hypothesis/observable/direction/gates before any validation','persistence':'atomic final files using scratch temporary files outside watched artifact tree; per-state archive then aggregates every<=4 states; stop on save error'}
f=P/'protocol_T1_B_frozen.json'
if f.exists():assert json.loads(f.read_text())==protocol
else:f.write_text(json.dumps(protocol,indent=2))
(P/'protocol_T1_B_frozen.sha256').write_text(hashlib.sha256(f.read_bytes()).hexdigest())
for n in ['geometry.py','audit.py']:shutil.copyfile(A/n,P/n)
for src,dst in [('state_results.csv','T1A_state_results.csv'),('linked_geometry.csv','T1A_linked_geometry.csv'),('inherited_checkpoint_manifest.json','checkpoint_manifest.json'),('inherited_protocol_C1_frozen.json','inherited_protocol_C1_frozen.json')]:shutil.copyfile(A/src,P/dst)
(P/'source_locations.json').write_text(json.dumps({'T1A':str(A),'T1A_library_path':'/Leviathan/Repro/E15_T1_A'},indent=2))
(P/'progress.md').write_text('# E15-T1-B — progreso\n\n0/80 estados nuevos completados;80 pendientes. Última tarea:verificación de insumos y congelación del protocolo. Radios:'+str(protocol['radii'])+'; primario:'+str(protocol['primary_radius'])+'.\n\nGeometría/checkpoints intactos;C1-A INCONCLUSIVE;T1A clasificaciones intactas. Manifest T1A:2193 archivos disponibles correctos;un temporal histórico ausente,finales780/780 verificados;80 checkpoints y80 ZIP íntegros. Ver input_integrity.json.\n\nNo resultados nuevos abiertos antes de congelar radios/análisis. Reanudar con run_common.py y conservar result.json confirmados.\n')
for n in ['common_radius_results.csv','correlations.csv','residuals.csv','positive_cases.csv','task_log.csv']:(P/n).write_text('status\nPENDING\n')
(P/'manifest.csv').write_text('path,bytes,sha256\n')
print(json.dumps({'radii':protocol['radii'],'primary':protocol['primary_radius'],'hash':hashlib.sha256(f.read_bytes()).hexdigest()},indent=2))
